  AxSymRun3.sr_vars_lt (s_next ss) (s_regs ss) = true /\ AxSymRun3.kn_vars_lt (s_next ss) (s_know ss) = true
  /\ wl_vars_lt (s_next ss) w = true /\ s_log ss = [].
