Fixpoint wslots (m : word -> option byte) (a : Z) (vs : list word) : word -> option byte :=
  match vs with [] => m | v :: r => wslots (wbytes m (Z_to_bv 64 a) (word_to_le_bytes 8 v)) (a + 8) r end.

